-- Original idle screen for mpv PlayKit.
--
-- The visual design is the mpv OSC idle badge (a glowing concentric-circle
-- play mark with a wordmark underneath), as drawn by mpv's player/lua/osc.lua.
-- mpv is licensed GPL-2.0-or-later / LGPL-2.1-or-later; its license texts are
-- shipped in the package's licenses/ directory.  The implementation here is
-- original: every shape is generated by the code below and no baseline Lua is
-- copied.

local mp = require "mp"
local options = require "mp.options"

local settings = {
	label = "mpv_PlayKit",
}
options.read_options(settings)

local overlay = mp.create_osd_overlay("ass-events")
overlay.z = 10

local menu_type = nil

-- Circle as a dense polygon.  Coordinates are in the 1800x1800 logo space
-- used by mpv's OSC logo; \p5 scales that space down by 16.
local function circle_path(center_x, center_y, radius)
	local segments = 180
	local points = {}
	for index = 0, segments - 1 do
		local angle = (math.pi * 2 * index) / segments
		points[#points + 1] = string.format(
			"%s %d %d",
			index == 0 and "m" or "l",
			math.floor(center_x + math.cos(angle) * radius + 0.5),
			math.floor(center_y + math.sin(angle) * radius + 0.5)
		)
	end
	points[#points + 1] = string.format(
		"l %d %d",
		math.floor(center_x + radius + 0.5),
		math.floor(center_y + 0.5)
	)
	return table.concat(points, " ")
end

-- Play triangle.  Three straight edges; at the rendered size this is visually
-- identical to mpv's OSC mark, whose "curves" have control points within a
-- third of a unit of the straight edges.
local function triangle_path()
	return "m 762 1113 l 762 708 l 1119 911 l 762 1113"
end

local function event(prefix, path)
	return "{" .. prefix .. "}" .. path
end

local function menu_is_open()
	return menu_type ~= nil and menu_type ~= "" and menu_type ~= "undefined"
end

local function update()
	if mp.get_property_native("idle-active") ~= true or menu_is_open() then
		overlay:remove()
		return
	end

	local width = mp.get_property_number("osd-dimensions/w", 0) or 0
	local height = mp.get_property_number("osd-dimensions/h", 0) or 0
	if width < 64 or height < 64 then
		overlay:remove()
		return
	end

	local hidpi = mp.get_property_number("display-hidpi-scale", 1) or 1
	local fullscreen = mp.get_property_native("fullscreen") == true
	local scale = hidpi * (fullscreen and 1.3 or 1)

	local logo_size = 112.5 * scale
	local font_size = 40 * scale
	local spacing = 10 * scale
	local total_height = logo_size + font_size + spacing
	local icon_x = (width - logo_size) / 2
	local icon_y = (height - total_height) / 2
	local text_y = icon_y + logo_size + spacing
	local scale_percent = scale * 100

	local prefix = string.format(
		"\\rDefault\\an7\\pos(%.2f,%.2f)\\fscx%.2f\\fscy%.2f\\p5\\bord0\\shad0",
		icon_x, icon_y, scale_percent, scale_percent
	)

	local outer = circle_path(895, 905, 895)
	local ring_dark = circle_path(925, 880, 838)
	local ring_deep = circle_path(977, 828, 628)
	local core = circle_path(897, 910, 400)
	local triangle = triangle_path()

	local lines = {
		-- Soft light-purple glow around the outer edge.
		event(prefix .. "\\1a&HFF&\\3c&HF593C8&\\3a&H00&\\bord2\\blur8", outer),
		-- Outer light-grey rim.
		event(prefix .. "\\1c&HE5E5E5&\\1a&H00&\\bord0\\blur0", outer),
		-- Dark purple rings.
		event(prefix .. "\\1c&H682167&\\1a&H00&\\bord0\\blur0", ring_dark),
		event(prefix .. "\\1c&H430142&\\1a&H00&\\bord0\\blur0", ring_deep),
		-- Light inner disc.
		event(prefix .. "\\1c&HDDDBDD&\\1a&H00&\\bord0\\blur0", core),
		-- Purple play mark.
		event(prefix .. "\\1c&H691F69&\\1a&H00&\\bord0\\blur0", triangle),
	}

	local label = tostring(settings.label or "")
	if label ~= "" then
		lines[#lines + 1] = string.format(
			"{\\an8\\pos(%.2f,%.2f)\\fn%s\\fs%.2f\\b0\\1c&HFFFFFF&\\1a&H00&\\bord0\\shad0}%s",
			width / 2, text_y, "sans-serif", font_size, label:gsub("([{}])", "\\%1")
		)
	end

	-- Tell mpv the coordinate space explicitly.  Without this, mpv interprets
	-- the ASS coordinates in its HiDPI-scaled space and the badge drifts to
	-- the bottom-right corner on scaled displays.
	overlay.res_x = width
	overlay.res_y = height
	overlay.data = table.concat(lines, "\n")
	overlay:update()
end

mp.observe_property("idle-active", "bool", update)
mp.observe_property("osd-dimensions", "native", update)
mp.observe_property("display-hidpi-scale", "number", update)
mp.observe_property("fullscreen", "bool", update)
mp.observe_property("user-data/uosc/menu/type", "string", function(_, value)
	menu_type = value
	update()
end)
mp.register_event("file-loaded", update)
mp.register_event("end-file", update)
